import numpy as np

def poly(xs: list, x: float):
    return sum(coeff * (x ** i) for i, coeff in enumerate(xs))

def find_zero(xs: list):
    # Using NumPy's roots function to find the roots of the polynomial
    roots = np.roots(xs)
    # We only need to return one root, assuming it is real and the first one
    real_roots = [r.real for r in roots if np.isreal(r)]
    if real_roots:
        return real_roots[0]  # Return the first real root found
    return None  # In case no real root is found

